using ModelContextProtocol;
using McpHttpServer.Tools;

var builder = WebApplication.CreateBuilder(args);

builder.Services
    .AddMcpServer()
    .WithHttpTransport()
    .WithToolsFromAssembly()
    .WithResources();

var app = builder.Build();

// Map the MCP endpoint at /mcp (handles Streamable HTTP transport)
app.MapMcp();

app.Run();

// Resource provider that exposes configuration data
public class ConfigResourceProvider : McpResourceProvider
{
    public override IAsyncEnumerable<McpResourceTemplate> GetResourceTemplatesAsync(
        CancellationToken cancellationToken = default)
    {
        return AsyncEnumerable.Empty<McpResourceTemplate>();
    }

    public override async IAsyncEnumerable<McpResource> ListResourcesAsync(
        [System.Runtime.CompilerServices.EnumeratorCancellation] CancellationToken cancellationToken = default)
    {
        yield return new McpResource
        {
            Uri = "config://app/settings",
            Name = "Application Settings",
            Description = "Current application configuration",
            MimeType = "application/json"
        };
    }

    public override Task<McpResourceContent> ReadResourceAsync(
        string uri, CancellationToken cancellationToken = default)
    {
        if (uri == "config://app/settings")
        {
            var json = """
                {
                    "app.name": "MyService",
                    "app.version": "1.0.0",
                    "app.environment": "production",
                    "app.max_connections": "100"
                }
                """;

            return Task.FromResult<McpResourceContent>(new McpResourceContent
            {
                Uri = uri,
                MimeType = "application/json",
                Text = json
            });
        }

        throw new McpException($"Resource not found: {uri}");
    }
}

