using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpHttpServer.Resources;

[McpServerResourceType]
public class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "Application Settings",
        MimeType = "application/json"), Description("Current application configuration as JSON")]
    public static string GetAppSettings()
    {
        var settings = new Dictionary<string, string>
        {
            ["app.name"] = "MyService",
            ["app.version"] = "1.0.0",
            ["app.environment"] = "production",
            ["app.max_connections"] = "100"
        };

        return JsonSerializer.Serialize(settings, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/features", Name = "Feature Flags",
        MimeType = "application/json"), Description("Current feature flag settings")]
    public static string GetFeatureFlags()
    {
        var flags = new Dictionary<string, bool>
        {
            ["dark_mode"] = true,
            ["beta_features"] = false,
            ["analytics"] = true
        };

        return JsonSerializer.Serialize(flags, new JsonSerializerOptions { WriteIndented = true });
    }
}

